ALTER TABLE public.alert_events ADD COLUMN confidence text NOT NULL DEFAULT 'sure' CHECK(confidence IN ('sure','likely','can''t tell')), ADD COLUMN push_sent_at timestamptz;
CREATE TABLE public.alert_settings(tenant_id uuid PRIMARY KEY REFERENCES public.tenants(id),watches jsonb NOT NULL DEFAULT '{"Sales":"Normal","Missing data":"Normal","Costs":"Normal","Money":"Normal","People":"Normal","Books":"Normal"}',role_delivery jsonb NOT NULL DEFAULT '{}',sales_grace_days integer NOT NULL DEFAULT 2 CHECK(sales_grace_days BETWEEN 0 AND 14),summary_time time NOT NULL DEFAULT '09:00',quiet_start time NOT NULL DEFAULT '23:00',quiet_end time NOT NULL DEFAULT '08:00',updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.alert_settings TO authenticated; GRANT ALL ON public.alert_settings TO service_role; ALTER TABLE public.alert_settings ENABLE ROW LEVEL SECURITY; CREATE POLICY alert_settings_read ON public.alert_settings FOR SELECT TO authenticated USING(public.user_has_tenant(auth.uid(),tenant_id) OR public.is_super_admin(auth.uid()));
CREATE TABLE public.alert_asks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),created_by uuid NOT NULL,venue_id uuid NOT NULL REFERENCES public.venues(id),title text NOT NULL,weekday integer NOT NULL CHECK(weekday BETWEEN 0 AND 6),check_time time NOT NULL,threshold numeric NOT NULL CHECK(threshold>=0),mode text NOT NULL DEFAULT 'absolute' CHECK(mode IN ('absolute','below_usual')),target_role text NOT NULL,enabled boolean NOT NULL DEFAULT true,source_action_id uuid UNIQUE REFERENCES public.bani_pending_actions(id),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.alert_asks TO authenticated; GRANT ALL ON public.alert_asks TO service_role; ALTER TABLE public.alert_asks ENABLE ROW LEVEL SECURITY; CREATE POLICY alert_asks_read ON public.alert_asks FOR SELECT TO authenticated USING(public.smart_alert_can_read(tenant_id,venue_id,'sales'));
CREATE TABLE public.alert_feed_coverage(id text NOT NULL,tenant_id uuid NOT NULL REFERENCES public.tenants(id),kind text NOT NULL,name text NOT NULL,venue_id uuid REFERENCES public.venues(id),complete_up_to date,status text NOT NULL CHECK(status IN ('up to date','behind','never connected')),PRIMARY KEY(tenant_id,id));
GRANT SELECT ON public.alert_feed_coverage TO authenticated; GRANT ALL ON public.alert_feed_coverage TO service_role; ALTER TABLE public.alert_feed_coverage ENABLE ROW LEVEL SECURITY; CREATE POLICY alert_coverage_read ON public.alert_feed_coverage FOR SELECT TO authenticated USING(public.smart_alert_can_read(tenant_id,venue_id,CASE kind WHEN 'sales' THEN 'sales' WHEN 'card' THEN 'payments' WHEN 'bill' THEN 'expenses' ELSE 'bank' END));
CREATE TABLE public.alert_delivery_runs(tenant_id uuid NOT NULL REFERENCES public.tenants(id),user_id uuid NOT NULL,local_day date NOT NULL,sent_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,user_id,local_day)); GRANT ALL ON public.alert_delivery_runs TO service_role; ALTER TABLE public.alert_delivery_runs ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.smart_alert_save_settings(t uuid,options jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k text;v text;r text;BEGIN
IF auth.uid() IS NULL OR NOT (is_super_admin(auth.uid()) OR EXISTS(SELECT 1 FROM tenant_members WHERE tenant_id=t AND user_id=auth.uid() AND role IN ('owner','admin','manager'))) THEN RAISE EXCEPTION 'Manager access required';END IF;
IF jsonb_typeof(options)<>'object' OR options::text LIKE '%null%' THEN RAISE EXCEPTION 'Invalid settings';END IF;
IF options ? 'watches' THEN FOR k,v IN SELECT * FROM jsonb_each_text(options->'watches') LOOP IF k NOT IN ('Sales','Missing data','Costs','Money','People','Books') OR v NOT IN ('Off','Fewer','Normal','More') THEN RAISE EXCEPTION 'Invalid watch level';END IF;END LOOP;END IF;
IF options ? 'role_delivery' THEN FOR r IN SELECT jsonb_object_keys(options->'role_delivery') LOOP IF NOT EXISTS(SELECT 1 FROM tenant_members WHERE tenant_id=t AND role=r) THEN RAISE EXCEPTION 'Unknown role';END IF; IF jsonb_typeof(options->'role_delivery'->r->'areas')<>'array' OR jsonb_typeof(options->'role_delivery'->r->'urgent_push')<>'boolean' OR jsonb_typeof(options->'role_delivery'->r->'daily_summary')<>'boolean' THEN RAISE EXCEPTION 'Invalid role delivery';END IF; FOR v IN SELECT jsonb_array_elements_text(options->'role_delivery'->r->'areas') LOOP IF v NOT IN ('Sales','Missing data','Costs','Money','People','Books') THEN RAISE EXCEPTION 'Invalid area';END IF;END LOOP;END LOOP;END IF;
INSERT INTO alert_settings(tenant_id) VALUES(t) ON CONFLICT DO NOTHING;
UPDATE alert_settings SET watches=coalesce(options->'watches',watches),role_delivery=coalesce(options->'role_delivery',role_delivery),sales_grace_days=coalesce((options->>'sales_grace_days')::integer,sales_grace_days),summary_time=coalesce((options->>'summary_time')::time,summary_time),quiet_start=coalesce((options->>'quiet_start')::time,quiet_start),quiet_end=coalesce((options->>'quiet_end')::time,quiet_end),updated_at=now() WHERE tenant_id=t;
END $$; REVOKE ALL ON FUNCTION public.smart_alert_save_settings(uuid,jsonb) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.smart_alert_save_settings(uuid,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.smart_alert_toggle_ask(t uuid,ident uuid,on_off boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a alert_asks;BEGIN SELECT * INTO a FROM alert_asks WHERE tenant_id=t AND id=ident FOR UPDATE;IF a.id IS NULL OR NOT smart_alert_can_read(t,a.venue_id,'sales') OR NOT(a.created_by=auth.uid() OR is_super_admin(auth.uid()) OR EXISTS(SELECT 1 FROM tenant_members WHERE tenant_id=t AND user_id=auth.uid() AND role IN ('owner','admin','manager'))) THEN RAISE EXCEPTION 'Access denied';END IF;UPDATE alert_asks SET enabled=on_off WHERE id=ident; END $$;REVOKE ALL ON FUNCTION public.smart_alert_toggle_ask(uuid,uuid,boolean) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.smart_alert_toggle_ask(uuid,uuid,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.smart_alert_keep_ask(t uuid,ident uuid,decision text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a bani_pending_actions;p jsonb;BEGIN SELECT * INTO a FROM bani_pending_actions WHERE id=ident AND tenant_id=t AND user_id=auth.uid() FOR UPDATE;IF a.id IS NULL OR a.kind<>'create_alert_ask' OR a.status<>'pending' OR a.expires_at<now() THEN RAISE EXCEPTION 'Card unavailable or expired';END IF;IF decision NOT IN ('confirm','below_usual','cancel') THEN RAISE EXCEPTION 'Invalid decision';END IF;IF decision='cancel' THEN UPDATE bani_pending_actions SET status='cancelled',resolved_at=now() WHERE id=ident;RETURN jsonb_build_object('ok',true,'message','Cancelled — nothing changed.');END IF;p:=a.payload;
IF NOT smart_alert_can_read(t,(p->>'venue_id')::uuid,'sales') OR NOT EXISTS(SELECT 1 FROM venues WHERE tenant_id=t AND id=(p->>'venue_id')::uuid) OR NOT EXISTS(SELECT 1 FROM tenant_members WHERE tenant_id=t AND role=p->>'target_role') THEN RAISE EXCEPTION 'Venue or recipient unavailable';END IF;
INSERT INTO alert_asks(tenant_id,created_by,venue_id,title,weekday,check_time,threshold,mode,target_role,source_action_id) VALUES(t,auth.uid(),(p->>'venue_id')::uuid,a.title,(p->>'weekday')::integer,(p->>'check_time')::time,(p->>'threshold')::numeric,CASE WHEN decision='below_usual' THEN 'below_usual' ELSE 'absolute' END,p->>'target_role',ident);UPDATE bani_pending_actions SET status='confirmed',resolved_at=now() WHERE id=ident;RETURN jsonb_build_object('ok',true,'asks_changed',true,'message','Kept — Bani will watch this.');END $$;REVOKE ALL ON FUNCTION public.smart_alert_keep_ask(uuid,uuid,text) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.smart_alert_keep_ask(uuid,uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.smart_alert_sync(t uuid,day date,candidates jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c jsonb;old alert_events;ident uuid;fired jsonb:='[]';seen text[]:='{}';k text;m alert_mutes;st text;v uuid;result jsonb; BEGIN
IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Server only';END IF;PERFORM pg_advisory_xact_lock(hashtext('smart-alert:'||t::text));
FOR c IN SELECT value FROM jsonb_array_elements(candidates) LOOP v:=nullif(c->>'venue_id','')::uuid;k:=(c->>'kind')||'|'||coalesce(v::text,'')||'|'||(c->>'subject');seen:=array_append(seen,k);st:=CASE WHEN c->'payload'->>'summary_only'='true' OR c->>'severity'='info' THEN 'summary' ELSE 'open' END;
SELECT * INTO old FROM alert_events WHERE tenant_id=t AND kind=c->>'kind' AND venue_id IS NOT DISTINCT FROM v AND subject=c->>'subject' ORDER BY created_at DESC LIMIT 1;
IF old.id IS NOT NULL AND old.status='done' AND old.closed_by IS DISTINCT FROM 'bani' THEN CONTINUE;END IF;
FOR m IN SELECT * FROM alert_mutes WHERE tenant_id=t AND active AND (kind IS NULL OR kind=c->>'kind') AND (area IS NULL OR area=c->>'area') AND (venue_id IS NULL OR venue_id=v) LOOP
IF m.scope='summary_only' AND st<>'muted' THEN st:='summary'; ELSIF m.scope='until' AND m.until_date>=day OR m.scope='off' OR m.scope='bigger_only' AND coalesce((c->'payload'->>'change_percent')::numeric,0)<=coalesce(m.threshold,60) THEN st:='muted';END IF;END LOOP;
IF old.payload->>'snoozed_until' IS NOT NULL AND (old.payload->>'snoozed_until')::date>=day THEN st:='muted';END IF;
IF old.id IS NOT NULL AND old.status IN ('open','muted','summary') THEN UPDATE alert_events SET title=c->>'title',why=c->>'why',baseline=(c->>'baseline')::numeric,actual=(c->>'actual')::numeric,severity=c->>'severity',confidence=coalesce(c->'payload'->>'confidence','sure'),payload=coalesce(old.payload,'{}')||coalesce(c->'payload','{}'),action_path=c->>'action_path',status=st,updated_at=now() WHERE id=old.id;
ELSE INSERT INTO alert_events(tenant_id,kind,subject,fired_for_date,severity,status,area,venue_id,title,why,baseline,actual,action_path,payload,confidence) VALUES(t,c->>'kind',c->>'subject',coalesce((c->>'date')::date,day),c->>'severity',st,c->>'area',v,c->>'title',c->>'why',(c->>'baseline')::numeric,(c->>'actual')::numeric,c->>'action_path',coalesce(c->'payload','{}'),coalesce(c->'payload'->>'confidence','sure')) RETURNING id INTO ident;fired:=fired||jsonb_build_array(c||jsonb_build_object('id',ident,'status',st));END IF;END LOOP;
UPDATE alert_events SET status='done',closed_by='bani',closed_at=now(),updated_at=now() WHERE tenant_id=t AND kind IS NOT NULL AND status IN ('open','muted','summary') AND NOT(kind||'|'||coalesce(venue_id::text,'')||'|'||subject=ANY(seen));
result:=jsonb_build_object('fired',fired,'evaluated',jsonb_array_length(candidates));INSERT INTO alert_evaluation_runs(tenant_id,last_day,last_result) VALUES(t,day,result) ON CONFLICT(tenant_id) DO UPDATE SET last_day=day,last_result=result,updated_at=now();RETURN result;END $$;
REVOKE ALL ON FUNCTION public.smart_alert_sync(uuid,date,jsonb) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.smart_alert_sync(uuid,date,jsonb) TO service_role;
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.smart_alert_action(uuid,uuid,text,jsonb)'::regprocedure) INTO def;def:=replace(def,'SET status=''muted'',updated_at=now() WHERE id=ident; RETURN;','SET status=CASE WHEN sc=''summary_only'' THEN ''summary'' ELSE ''muted'' END,updated_at=now() WHERE id=ident; RETURN;');EXECUTE def;END $$;